Class Cronometro
  Define total As Integer;

  Method Constructor()
    This.total <- 0;
  EndMethod

  Method Avanzar(segundos As Integer)
    This.total <- This.total + segundos;
  EndMethod

  Method Lectura() As String
    Define horas As Integer <- This.total Div 3600;
    Define minutos As Integer <- This.total Mod 3600 Div 60;
    Return toText(horas) + " h " + toText(minutos) + " min " + toText(This.total Mod 60) + " s";
  EndMethod
EndClass

Algorithm Carrera
  Define reloj As Cronometro <- New Cronometro();
  Define segundos As Integer;
  Read segundos;
  reloj.Avanzar(segundos);
  Read segundos;
  reloj.Avanzar(segundos);
  Write reloj.Lectura();
EndAlgorithm
